// Loads the Rust host compiled to WebAssembly. The files under ./wasm are
// generated by `just wasm` and are not committed.
import init from "./wasm/airport_sim_wasm.js";
import wasmUrl from "./wasm/airport_sim_wasm_bg.wasm" with { type: "file" };

export * from "./wasm/airport_sim_wasm.js";

export async function loadSim(): Promise<void> {
  await init({ module_or_path: wasmUrl });
}
